/* ============================================
   Embedded currency font (Arimo, Apache-2.0)
   ------------------------------------------------
   jsPDF's built-in fonts use WinAnsi encoding and cannot draw the
   Indian Rupee sign (U+20B9) and similar currency glyphs. This module
   ships a subset of Arimo (metric-compatible with Helvetica/Arial) that
   contains those glyphs, so amounts can render their real symbol.
   Source: https://github.com/googlefonts/Arimo (Apache License 2.0)
   ============================================ */
window.CURRENCY_FONT = {
    regular: '',
    bold: ''
};
